<?php
declare(strict_types=1); namespace App\Controllers; use App\Services\PreRegistrationService;
final class PreRegistrationController { public function __construct(private readonly PreRegistrationService $s) {} private function actorRole(array $x): string { return (string) ($x['subrole'] ?? $x['role'] ?? ''); } public function create(array $p,array $x):array{try{return['preRegistration'=>$this->s->create($p['cedula']??'',$p['role']??'',(int)$x['sub'],$this->actorRole($x))];}catch(\PDOException){http_response_code(409);return['message'=>'Ya existe un registro asociado a esta cédula.'];}catch(\Throwable $e){http_response_code(422);return['message'=>$e->getMessage()];}} public function verify(string $c):array{$r=$this->s->findPending($c);if(!$r){http_response_code(404);return['message'=>'Pre-registro no disponible.'];}return $r;} public function list(int $p,array $x):array{return $this->s->list($p,$this->actorRole($x));} public function toggle(int $id,array $x):array{try{$this->s->toggle($id,$this->actorRole($x),(string)($x['cedula']??''));return['ok'=>true];}catch(\DomainException $e){http_response_code(403);return['message'=>$e->getMessage()];}} public function complete(array $p):array{try{$this->s->complete($p['cedula']??'',$p['firstNames']??'',$p['lastNames']??'');return['ok'=>true];}catch(\Throwable $e){http_response_code(409);return['message'=>$e->getMessage()];}}}
